# ───────────────────────── 레지스트리 ─────────────────────────
def _rows(path, ncol):
    out = []
    for n, line in enumerate(io.open(path, encoding="utf-8"), 1):
        line = line.rstrip("\n")
        if not line.strip() or line.startswith("#"):
            continue
        cols = line.split("\t")
        if len(cols) < ncol:
            raise ValueError(f"{os.path.basename(path)}:{n} 열 {len(cols)}개 — {ncol}개가 필요하다")
        out.append(cols + [""] * (ncol + 2 - len(cols)))
    return out

def load_clusters(path=None):
    """clusters.tsv — cluster·lane·type·name·scope·match·status·hub. 순서가 판정 순서다."""
    cs, seen = [], set()
    for cid, lane, typ, name, scope, rx, status, hub, *_ in _rows(path or CLUSTERS_F, 7):
        if cid in seen:
            raise ValueError(f"clusters.tsv 중복 id: {cid}")
        if typ not in TYPES or status not in STATUSES:
            raise ValueError(f"clusters.tsv {cid}: type '{typ}' 또는 status '{status}'가 정의 밖")
        seen.add(cid)
        cs.append(dict(id=cid, lane=lane, type=typ, name=name, scope=scope, status=status, hub=hub,
                       rx=re.compile(rx, re.I) if rx else None))
    return cs

def load_entities(path=None):
    """entities.tsv — name·kind·match(·owns: company만 — 그 회사의 도구 이름, 쉼표)."""
    return [dict(name=n, kind=k, rx=re.compile(rx, re.I), owns=[x.strip() for x in (rest[0] if rest else "").split(",") if x.strip()])
            for n, k, rx, *rest in _rows(path or ENTITIES_F, 3)]

def lanes(clusters):
    return list(dict.fromkeys(c["lane"] for c in clusters))


# ───────────────────────── 분류 ─────────────────────────
def classify(kw, clusters, entities, extra=""):
    """메인 키워드로 클러스터를 고르고(DEPRECATED는 건너뛴다), 키워드·제목(extra)에서 entity를 뽑는다."""
    c = next((c for c in clusters if c["status"] != "DEPRECATED" and c["rx"] and c["rx"].search(kw)), None)
    text = f"{kw} {extra}"
    return dict(cluster=c["id"] if c else "", lane=c["lane"] if c else "", type=c["type"] if c else "",
                entity=[e["name"] for e in entities if e["kind"] != "company" and e["rx"].search(text)])

def suggest_intent(kw):
    return next(name for name, rx in INTENT_RULES if re.search(rx, kw, re.I))


# ───────────────────────── 프론트매터 ─────────────────────────
FM_RE = re.compile(r"^---\n(.*?)\n---\n", re.S)

def _val(raw):
    v = re.sub(r"\s+#.*$", "", raw).strip()
    return v.strip('"\'')

def parse(text):
    """{필드: 값} — 값은 문자열, 대괄호 목록은 list. 프론트매터가 없으면 None."""
    m = FM_RE.match(text)
    if not m:
        return None
    d = {}
    for line in m.group(1).split("\n"):
        k = re.match(r"^([A-Za-z_]+):[ \t]?(.*)$", line)
        if not k:
            continue
        v = _val(k.group(2))
        d[k.group(1)] = [x.strip().strip('"\'') for x in v[1:-1].split(",") if x.strip()] if v.startswith("[") and v.endswith("]") else v
    return d

def fmt(field, value):
    return f"{field}: [{', '.join(value)}]" if isinstance(value, list) else f"{field}: {value}"

def set_fields(text, values):
    """프론트매터 줄만 고친다 — 있는 필드는 그 줄을 바꾸고, 없는 필드는 정한 자리에 넣는다. 본문은 그대로 돌려준다.
    자리: category는 series(없으면 platform) 뒤, lane·cluster·intent·entity는 form(없으면 category) 뒤에 이 순서로."""
    m = FM_RE.match(text)
    if not m:
        raise ValueError("프론트매터 없음")
    lines = m.group(1).split("\n")
    key = lambda l: (re.match(r"^([A-Za-z_]+):", l) or [None, None])[1]
    for f in FIELDS:
        if f not in values:
            continue
        new = fmt(f, values[f])
        idx = next((i for i, l in enumerate(lines) if key(l) == f), None)
        if idx is not None:
            lines[idx] = new
            continue
        # 앞서 넣은 필드(lane → cluster → intent) 바로 뒤, 없으면 form → category → series 뒤
        anchors = ("series", "platform") if f == "category" else tuple(reversed(FIELDS[1:FIELDS.index(f)])) + ("form", "category", "series")
        at = next((i for a in anchors for i, l in enumerate(lines) if key(l) == a), len(lines) - 1)
        lines.insert(at + 1, new)
    return "---\n" + "\n".join(lines) + "\n---\n" + text[m.end():]


# ───────────────────────── 검사 ─────────────────────────
def is_new(meta):
    return (meta.get("created") or "") > MIGRATED_THROUGH

def validate(meta, clusters, entities):
    """[(FAIL|WARN, 코드, 내용)]. 빠진 필드는 새 글만 WARN(이전 원고는 마이그레이션 대상), 틀린 값은 FAIL."""
    out, by = [], {c["id"]: c for c in clusters}
    missing = [f for f in FIELDS if f not in meta or (f != "entity" and not meta[f])]   # entity: [] 는 '없음'이라는 값이다
    if missing:
        out.append(("WARN" if is_new(meta) else "FAIL", "M0", f"메타데이터 없음: {', '.join(missing)} — `blog_taxonomy.py classify \"메인 키워드\"`로 제안을 보고 채운다"))
    lane, cid, intent, ents, cat = (meta.get(k) for k in ("lane", "cluster", "intent", "entity", "category"))
    if lane and lane not in lanes(clusters):
        out.append(("FAIL", "M1", f"lane '{lane}'이 clusters.tsv에 없다 — {'/'.join(lanes(clusters))}"))
    if cid:
        c = by.get(cid)
        if not c:
            out.append(("FAIL", "M2", f"cluster '{cid}'가 clusters.tsv에 없다"))
        else:
            if lane and c["lane"] != lane:
                out.append(("FAIL", "M3", f"cluster '{cid}'는 '{c['lane']}' 레인인데 lane이 '{lane}'"))
            if c["status"] == "DEPRECATED" and is_new(meta):
                out.append(("FAIL", "M7", f"cluster '{cid}'({c['name']})는 DEPRECATED — 새 글은 다른 클러스터로"))
            # M8: 메인 키워드의 자동 분류와 다르면 확인하라고만 한다(사람이 고른 배정이 맞을 수 있다 — 72편처럼). 템플릿 예시 값을 그대로 베낀 원고를 잡는다
            kws = meta.get("keywords") if isinstance(meta.get("keywords"), list) else []
            auto = classify(kws[0], clusters, entities)["cluster"] if kws else ""
            if auto and auto != cid:
                out.append(("WARN", "M8", f"메인 키워드 '{kws[0]}'의 자동 분류는 '{auto}'인데 cluster는 '{cid}' — 맞는지 확인(SKILL 템플릿 예시를 베꼈는지)"))
    if intent and intent not in INTENTS:
        out.append(("FAIL", "M4", f"intent '{intent}'가 정의 밖 — {'/'.join(INTENTS)}"))
    if ents not in (None, ""):
        if not isinstance(ents, list):
            out.append(("FAIL", "M5", f"entity는 [이름, …] 목록으로 쓴다: '{ents}'"))
        else:
            known = {e["name"] for e in entities}
            bad = [e for e in ents if e not in known]
            if bad:
                out.append(("FAIL", "M5", f"entity {bad}가 entities.tsv에 없다"))
    if cat and cat not in CATEGORIES:
        out.append(("FAIL", "M6", f"category '{cat}'는 블로그에 없는 카테고리 — {'/'.join(CATEGORIES)}"))
    return out

