# ───────────────────────── 카테고리 불일치 ─────────────────────────
def discrepancies(expected, live):
    """expected {글: 기준 카테고리}, live {글: 네이버 실제 카테고리} → 다른 글만 [(글, 기준, 실제, 'OPEN')]. 실제 값을 모르는 글은 뺀다."""
    return [(a, expected[a], live[a], "OPEN") for a in sorted(expected) if live.get(a) and live[a] != expected[a]]


def write_discrepancies(rows, path=None, checked=None):
    path = path or DISCREPANCY_F
    prev = {}
    if os.path.exists(path):
        for a, e, l, st, *rest in _rows(path, 4):
            prev[a] = (e, l, st, rest[0] if rest else "")
    day = checked or datetime.date.today().isoformat()
    out = {a: (e, l, st, day) for a, e, l, st in rows}
    for a, (e, l, st, d) in prev.items():   # 지난번에 열렸는데 이번에 맞으면 RESOLVED로 남긴다(기록이 사라지지 않게)
        if a not in out:
            out[a] = (e, l, "RESOLVED" if st == "OPEN" else st, day if st == "OPEN" else d)
    with io.open(path, "w", encoding="utf-8") as f:
        f.write("# 카테고리 불일치 — 원고 category:(기준값, naver-blog-draft STEP 4) ↔ 네이버 실제 발행 카테고리. blog_taxonomy.py discrepancy 가 다시 쓴다\n")
        f.write("# 형식: 글<TAB>기준 카테고리<TAB>실제 카테고리<TAB>상태(OPEN 미조치 / RESOLVED 맞춰짐)<TAB>확인일. 네이버 쪽 이동은 Thomas가 정한다 — 이 파일은 기록만 한다\n")
        for a in sorted(out):
            f.write("\t".join((a,) + out[a]) + "\n")
    return out


