INTENT_FACET = {"방법": "how_to", "비교": "comparison", "문제해결": "problem", "뜻": "meaning", "판정": "eligibility", "계산": "calculation", "문구": "document"}
UPDATE_F = os.path.join(KW_DIR, "update_candidates.tsv")
# 생애주기 권한(Phase 3.5) — 실제로 쓰는 status 값(published·scheduled·draft)에만 권한을 준다. 새 status를 만들지 않는다.
