#     73편(수수료 원문 검증 대기)이 hold가 되자 그 키워드가 CREATE_NEW로 바뀌어, 다시 올라올 때 중복될 뻔했다. 행동 값은 review_draft 그대로(큐가 읽는 값 불변)
AUTHORITY = {"published": 2, "scheduled": 2, "draft": 1, "hold": 1}
# 독립 검색 수요(Phase 4에서 kw_pipeline이 넣는다). True/False/None도 받는다(옛 호출): True → CONFIRMED, False·None → UNKNOWN
DEMANDS = ("CONFIRMED", "WEAK", "UNKNOWN")

# 수요 근거 → 3상태(Phase 4). 필드를 근거 태그로 바꾸는 일은 kw_pipeline이 하고, 태그 → 상태 규칙은 여기 하나다.
# 근거가 없는 것은 '수요 없음'이 아니다 — 검색량 0·빈 값은 API가 돌려주지 않은 말일 수 있다(missing ≠ zero) → UNKNOWN
DEMAND_STRONG = ("autocomplete_exact", "monthly_volume", "search_inflow")
DEMAND_WEAK = ("autocomplete_near", "google_autocomplete", "volume_floor", "related_keyword")

def demand_from_evidence(tags):
    tags = set(tags or ())
    return "CONFIRMED" if tags & set(DEMAND_STRONG) else "WEAK" if tags & set(DEMAND_WEAK) else "UNKNOWN"

def demand_state(d):
    if d is True:
        return "CONFIRMED"
    if d in (False, None, ""):
        return "UNKNOWN"
    d = str(d).upper()
    if d not in DEMANDS:
        raise ValueError(f"demand '{d}'는 {'/'.join(DEMANDS)} 중 하나")
    return d

def _facet_words():
    return sorted(((w, f) for f, ws in FACETS for w in ws), key=lambda x: -len(x[0]))

def analyze_kw(kw, entities):
    """키워드 → (core 낱말 목록, 갈래 집합, entity 목록). 도구 이름을 지운 뒤 낱말마다 끝의 질문어를 떼어 갈래로 옮긴다."""
    s = kw.lower()
    ents = []
    for e in entities:                      # 도구·플랫폼·제조사 먼저 지운다('구글 비즈니스 프로필'의 구글은 회사가 아니다)
        if e["kind"] != "company" and e["rx"].search(s):
            ents.append(e["name"]); s = e["rx"].sub(" ", s)
    conflict = []
    for e in entities:                      # 남은 말의 회사 이름: core에서 지우고, 그 회사 제품이 아닌 도구와 함께면 기록
        if e["kind"] == "company" and e["rx"].search(s):
            s = e["rx"].sub(" ", s)
            if ents and not set(e["owns"]) & set(ents):
                conflict.append(f"{e['name']}↔{'·'.join(ents)}")
    core, fams, fw = [], set(), set()
    fword = dict((w, f) for w, f in _facet_words())
    toks = [re.sub(r"(으로|로)$", "", t) if len(t) > 2 and not t.endswith(("메뉴로", "경로")) else t for t in re.findall(r"[가-힣a-z0-9]+", s)]
    tail = True                              # 끝에서부터 질문어 구역 — 질문어가 아닌 말을 만나면 그 앞은 주제어
    for t in reversed(toks):
        if t in FACET_ANYWHERE:
            fams.add(fword[t]); fw.add(t); continue
        if DATE_RX.match(t):
            y = YEAR_RX.match(t)
            fams.add("deadline"); fw.add(f"20{y.group(1)}" if y and not t.endswith(("월", "일", "기")) else t); continue
        if tail:
            while t:
                hit = next(((w, f) for w, f in _facet_words() if t.endswith(w)), None)
                if not hit:
                    break
                fams.add(hit[1]); fw.add(FACET_SYN.get(hit[0], hit[0])); t = t[:-len(hit[0])] + FACET_STEM.get(hit[0], "")
                if hit[0] in FACET_STEM:
                    break
            if t:
                tail = False
        if t and t not in GENERIC and len(t) >= 2:
            core.insert(0, t)
    if "how_to" in fams and len(fams - {"AI"}) > 1:
        fams.discard("how_to")      # '계산 방법'은 계산 질문이다('AI'는 수단 표지라 이 판단에 넣지 않는다)
        fw.discard("방법")
    return core, fams, ents, fw, conflict

def canon(kw, entities):
    """검색어의 표준형 — (붙여 쓴 주제 핵심, 질문 갈래, 도구). 같으면 표현만 다른 같은 검색어다(주휴수당 계산 = 주휴수당 계산법 = 주휴수당 계산 방법)."""
    core, fams, ents, fw, _ = analyze_kw(kw, entities)
    return ("".join(core), frozenset(fw), frozenset(ents))

# ───── 시간 판정(Phase 6.1, 2026-10-08) — 키워드의 연도·기간 표현이 지금 기준 어느 때인가. Slot C 순위의 보조 신호로만 쓴다.
# 중복 판정(decide)은 이것을 읽지 않는다. 이 블로그에 필요한 최소 규칙만 둔다(자연어 시간 파서가 아니다)
TEMPORAL = ("CURRENT_PERIOD", "UPCOMING_PERIOD", "EXPIRED_PERIOD", "TIMELESS", "AMBIGUOUS")
_T_YEAR4 = re.compile(r"(?<!\d)(20\d\d)(?:년도|년)?(?!\d)")
_T_YEAR2 = re.compile(r"(?<!\d)(\d\d)\s?(?:년도|년)")
_T_REL = {"올해": 0, "금년": 0, "내년": 1, "작년": -1, "전년": -1, "지난해": -1, "재작년": -2}
_T_REL_RX = re.compile("|".join(sorted(_T_REL, key=len, reverse=True)))
_T_HALF = re.compile(r"상반기|하반기|(?<!\d)([12])기(?![가-힣])")     # 부가세 1기·2기 = 상·하반기
_T_QUARTER = re.compile(r"(?<!\d)([1-4])\s?분기")
_T_MONTH = re.compile(r"(?<!\d)(1[0-2]|[1-9])\s?월(?!급|세)")
_T_WORD = re.compile(r"(20)?\d\d년도?|20\d\d|올해|금년|내년|작년|전년|지난해|재작년|상반기|하반기|[1-4]분기")

def _kst_today():
    return datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=9))).date()

def temporal_status(kw, today=None):
    """키워드 → dict(status, target_period, target_year, expressions). today는 'YYYY-MM-DD'나 date(없으면 KST 오늘).
    연도 없는 월·반기·분기가 지금보다 앞이면 매년 돌아오는 일일 수 있어 AMBIGUOUS다(지난 일로 보지 않는다).
    EXPIRED라고 검색 가치가 없다는 뜻이 아니다 — 소급·정정·지난 해 기준 확인 수요가 있다."""
    t = datetime.date.fromisoformat(today) if isinstance(today, str) else (today or _kst_today())
    s = kw.lower()
    exprs, years, ambiguous = [], set(), False
    for m in _T_YEAR4.finditer(s):
        exprs.append(m.group(0)); years.add(int(m.group(1)))
    for m in _T_YEAR2.finditer(s):
        if re.search(r"20$", s[:m.start()]):     # '2026년'의 뒷부분
            continue
        exprs.append(m.group(0))
        y = 2000 + int(m.group(1))
        if abs(y - t.year) <= 5:       # 26년·27년. 이 범위 밖의 두 자리('10년 근속')는 기간일 수 있다
            years.add(y)
        else:
            ambiguous = True
    for m in _T_REL_RX.finditer(s):
        exprs.append(m.group(0)); years.add(t.year + _T_REL[m.group(0)])
    subs = []    # (표기, 시작 월, 끝 월)
    for m in _T_HALF.finditer(s):
        h = 1 if m.group(0) == "상반기" or m.group(1) == "1" else 2
        subs.append((f"H{h}", 1 if h == 1 else 7, 6 if h == 1 else 12)); exprs.append(m.group(0))
    for m in _T_QUARTER.finditer(s):
        q = int(m.group(1)); subs.append((f"Q{q}", 3 * q - 2, 3 * q)); exprs.append(m.group(0))
    for m in _T_MONTH.finditer(s):
        mo = int(m.group(1)); subs.append((f"{mo:02d}", mo, mo)); exprs.append(m.group(0))
    out = lambda st, period="", year=None: dict(status=st, target_period=period, target_year=year, expressions=exprs)
    if not exprs:
        return out("TIMELESS")
    if ambiguous or len(years) > 1 or len(subs) > 1:     # 두 해 비교('2025 2026 최저임금') 등 — 자동 감점하지 않는다
        return out("AMBIGUOUS", "/".join(map(str, sorted(years))))
    y = next(iter(years)) if years else None
    if not subs:
        return out("CURRENT_PERIOD" if y == t.year else "UPCOMING_PERIOD" if y > t.year else "EXPIRED_PERIOD", str(y), y)
    tag, m0, m1 = subs[0]
    if y is None:                      # 연도 없는 월·반기·분기 — 올해의 그때로 본다. 이미 지났으면 다음 해 이야기일 수 있다
        if m0 <= t.month <= m1:
            return out("CURRENT_PERIOD", f"{t.year}-{tag}", t.year)
        return out("UPCOMING_PERIOD", f"{t.year}-{tag}", t.year) if m0 > t.month else out("AMBIGUOUS", f"매년 {tag}")
    now_i, a, b = t.year * 12 + t.month, y * 12 + m0, y * 12 + m1
    return out("CURRENT_PERIOD" if a <= now_i <= b else "UPCOMING_PERIOD" if a > now_i else "EXPIRED_PERIOD", f"{y}-{tag}", y)

def temporal_facets(kw, entities):
    """시점 표현(연도)만 뺀 세부 질문 갈래 — '26년 최저임금'의 '26년'은 판(版)이지 기한 질문이 아니다."""
    _, fams, _, fw, _ = analyze_kw(kw, entities)
    fams = set(fams) - {"AI"}
    years = {w for w in fw if re.fullmatch(r"20\d\d", w)}
    if "deadline" in fams and years and not any(_facet_of(w) == "deadline" or (DATE_RX.match(w) and w not in years) for w in fw):
        fams.discard("deadline")
    return fams

def temporal_relation(kw_a, kw_b, entities, clusters=None, today=None):
    """두 검색어의 시간 관계(내부 근거일 뿐 판정 enum이 아니다). 같은 클러스터·같은 세부 질문·같은 주제에서 대상 연도만 다르면
    YEAR_VARIANT — 중복이 아니라 서로 다른 해를 찾는 별개 검색일 수 있다. 새 글을 보장하지도 않는다(커버리지·수요는 판정이 본다). 그 밖은 NONE."""
    ta, tb = temporal_status(kw_a, today), temporal_status(kw_b, today)
    if not ta["target_year"] or not tb["target_year"] or ta["target_year"] == tb["target_year"]:
        return "NONE"
    if clusters is not None and classify(kw_a, clusters, entities)["cluster"] != classify(kw_b, clusters, entities)["cluster"]:
        return "NONE"
    if temporal_facets(kw_a, entities) != temporal_facets(kw_b, entities):
        return "NONE"
    ca = [w for w in analyze_kw(kw_a, entities)[0] if not _T_WORD.fullmatch(w)]
    cb = [w for w in analyze_kw(kw_b, entities)[0] if not _T_WORD.fullmatch(w)]
    return "YEAR_VARIANT" if ca and cb and core_sim_fuzzy(ca, cb) >= CORE_NEAR else "NONE"

def _bigrams(s):
    return {s[i:i + 2] for i in range(len(s) - 1)}

def _dice(x, y):
    """붙여 쓴 두 문자열의 2-gram 다이스 × 길이 비 — 길이 비를 곱해 '간이과세자' ⊂ '간이과세자세금계산서발행' 같은 머리말 포함을 같은 주제로 보지 않는다."""
    bx, by = _bigrams(x), _bigrams(y)
    if not bx or not by:
        return 0.0
    return 2 * len(bx & by) / (len(bx) + len(by)) * min(len(x), len(y)) / max(len(x), len(y))

def _tok_match(x, y):
    return x == y or (len(x) >= 2 and len(y) >= 2 and (x.startswith(y) or y.startswith(x)))

def core_sim_fuzzy(a, b):
    """낱말이 같거나 한쪽이 다른 쪽의 앞부분이면 같은 낱말로 센다('연차' ↔ '연차수당'). 붙여 쓴 문자열 다이스도 본다."""
    if not a or not b:
        return 0.0
    hit = sum(1 for x in set(a) if any(_tok_match(x, y) for y in set(b)))
    return round(max(hit / (len(set(a)) + len(set(b)) - hit), core_sim(a, b)), 3)

def core_sim(a, b):
    """core 둘의 유사도 — 낱말 자카드와 붙여 쓴 문자열 다이스(띄어쓰기만 다른 '알바근로계약서' ↔ '알바 근로계약서') 중 큰 값."""
    if not a or not b:
        return 0.0
    sa, sb = set(a), set(b)
    d = _dice("".join(a), "".join(b))
    # 다이스는 0.6 이상일 때만 쓴다 — '임금명세서' ↔ '거래명세서'(0.5)가 '명세서' 하나로 같은 주제가 되지 않게
    return round(max(len(sa & sb) / len(sa | sb), d if d >= 0.6 else 0.0), 3)

def _words(text):
    text = re.sub(r"\[이미지[^\]]*\]|!\[\[[^\]]*\]\]|https?://\S+", " ", text.lower())
    return re.findall(r"[가-힣a-z0-9]{2,}", text)

def _tfidf(docs):
    import math, collections
    df = collections.Counter(g for d in docs.values() for g in set(d))
    n, out = len(docs), {}
    for k, d in docs.items():
        c = collections.Counter(d)
        v = {g: tf * math.log(n / df[g]) for g, tf in c.items()}
        norm = math.sqrt(sum(x * x for x in v.values())) or 1
        out[k] = {g: x / norm for g, x in v.items()}
    return out

def _cos(a, b):
    return round(sum(x * b.get(g, 0) for g, x in a.items()), 3)

def _chargrams(s):
    s = re.sub(r"[^가-힣a-z0-9]", "", s.lower())
    return [s[i:i + k] for k in (2, 3) for i in range(len(s) - k + 1)]

def load_articles(paths=None):
    arts = []
    for p in paths or naver_files():
        t = io.open(p, encoding="utf-8").read()
        m = parse(t) or {}
        fm = FM_RE.match(t)
        body = t[fm.end():] if fm else t
        # 본문 첫머리의 발행정보 줄(> 카테고리: / > 태그:)은 내용이 아니라 표지다 — 커버리지·본문 유사도에서 뺀다(태그 '간판신고벌금'이 '벌금을 다룬다'로 세지던 것, 2026-10-08)
        body = re.sub(r"^> (카테고리|태그):.*$", "", body, flags=re.M)
        kws = m.get("keywords") if isinstance(m.get("keywords"), list) else []
        arts.append(dict(id=article_id(p), path=p, meta=m, title=m.get("title", ""), keywords=kws, status=m.get("status", ""),
                         cluster=m.get("cluster", ""), intent=m.get("intent", ""), entity=m.get("entity") or [],
                         h2=re.findall(r"^## (.+)$", body, re.M), body=body))
    return arts

def apply_live_status(articles, live):
    """실효 상태(Phase 4) — 볼트 status는 수동 발행을 늦게 따라간다. live = {logNo: 네이버 발행 제목}(RSS 등).
    올리기만 하고 내리지 않는다: 라이브에 안 보인다고 published를 draft로 낮추지 않는다(RSS는 최근 50편만 담는다).
    식별: ① 프론트매터 url의 logNo가 live에 있으면 naver_live_url ② url이 없고, 띄어쓰기 무시 제목이 live 제목 하나와 정확히 같고,
    그 logNo를 다른 글의 url이 갖고 있지 않을 때만 naver_live_title. 비슷한 제목으로는 올리지 않는다.
    글마다 frontmatter_status · status(실효) · status_source를 남긴다 — Corpus의 권한은 status(실효)를 본다."""
    live = live or {}
    nt = lambda t: re.sub(r"\s+", "", (t or "")).casefold()
    claimed = {m.group(1) for a in articles for m in [re.search(r"/(\d{9,})", a["meta"].get("url", "") or "")] if m}
    by_title = {}
    for ln, t in live.items():
        by_title.setdefault(nt(t), []).append(ln)
    for a in articles:
        fm = a.get("frontmatter_status", a["status"])
        a["frontmatter_status"], a["status"], a["status_source"] = fm, fm, "frontmatter"
        if fm == "published":
            continue
        m = re.search(r"/(\d{9,})", a["meta"].get("url", "") or "")
        if m and m.group(1) in live:
            a["status"], a["status_source"] = "published", "naver_live_url"
        elif not m:
            hits = [ln for ln in by_title.get(nt(a["title"]), []) if ln not in claimed]
            if len(hits) == 1:
                a["status"], a["status_source"] = "published", "naver_live_title"
    return articles

class Corpus:
    """기존 글 묶음과 그 벡터. 판정마다 다시 만들지 않는다."""
    def __init__(self, arts, clusters, entities):
        self.arts, self.cs, self.es = arts, clusters, entities
        import collections
        btok = {a["id"]: _words(a["body"]) for a in arts}
        ttok = {a["id"]: _chargrams(a["title"]) for a in arts}
        self.body, self.title = _tfidf(btok), _tfidf(ttok)
        self.df_body = collections.Counter(g for d in btok.values() for g in set(d))
        self.df_title = collections.Counter(g for d in ttok.values() for g in set(d))
        # 커버리지는 낱말 집합이 아니라 붙여 쓴 본문 문자열에서 찾는다 — '답변하기'·'근로계약서는'처럼 꼴이 바뀐 말도 잡게
        self.text = {a["id"]: re.sub(r"\s+", "", " ".join([a["title"], " ".join(a["keywords"]), " ".join(a["h2"]), a["body"]]).lower()) for a in arts}
        self.an = {}
        for a in arts:
            prim = analyze_kw(a["keywords"][0], entities) if a["keywords"] else ([], set(), [], set(), [])
            fams = set().union(*[analyze_kw(k, entities)[1] for k in a["keywords"]]) if a["keywords"] else set()
            if not fams - {"AI"} and a["intent"] in INTENT_FACET:   # 질문어가 없으면(AI 표지만 있어도) intent를 갈래로
                fams = fams | {INTENT_FACET[a["intent"]]}
            self.an[a["id"]] = dict(core=prim[0], cores=[analyze_kw(k, entities)[0] for k in a["keywords"]] or [prim[0]], fams=fams,
                                    fw=set().union(*[analyze_kw(k, entities)[3] for k in a["keywords"]]) if a["keywords"] else set(), pfams=set(prim[1]) - {"AI"}, ents=set(a["entity"]) | set(prim[2]), pents=set(prim[2]),
                                    canon={canon(k, entities) for k in a["keywords"]},
                                    kwn={re.sub(r"\s+", "", k.lower()) for k in a["keywords"]})

    def vec(self, body="", title=""):
        """후보 문서의 벡터 — 기존 말뭉치의 df로 잰다(후보가 말뭉치를 바꾸지 않게)."""
        import math, collections
        def one(tokens, df):
            n = len(self.arts)
            c = collections.Counter(tokens)
            v = {g: tf * math.log(n / df[g]) for g, tf in c.items() if df[g]}
            norm = math.sqrt(sum(x * x for x in v.values())) or 1
            return {g: x / norm for g, x in v.items()}
        return (one(_words(body), self.df_body) if body else {}), (one(_chargrams(title), self.df_title) if title else {})

def candidate(keyword, clusters, entities, keywords=(), title="", body="", intent="", cluster="", entity=None):
    """판정할 후보. 원고면 keywords·title·body·intent·cluster·entity를 프론트매터에서 채운다. 키워드만이면 classify·suggest_intent로 채운다."""
    kws = [keyword] + [k for k in keywords if k != keyword]
    c = classify(keyword, clusters, entities, " ".join(kws) + " " + title)
    prim = analyze_kw(keyword, entities)
    intent = intent or suggest_intent(keyword)
    fams = set().union(*[analyze_kw(k, entities)[1] for k in kws])
    if not fams - {"AI"} and intent in INTENT_FACET:   # 질문어가 없으면(AI 표지만 있어도) intent를 갈래로
        fams = fams | {INTENT_FACET[intent]}
    return dict(keyword=keyword, keywords=kws, title=title or keyword, body=body, fw=set(prim[3]), conflict=prim[4],
                cluster=cluster or c["cluster"], intent=intent,
                entity=set(entity if entity is not None else c["entity"]) | set(prim[2]),
                core=prim[0], fams=fams, pents=set(prim[2]),
                kwn={re.sub(r"\s+", "", k.lower()) for k in kws})

def _facet_of(word):
    return next((f for f, ws in FACETS if word in ws or word in (FACET_SYN.get(w, w) for w in ws)), None)

def _cover(word, art, facet=None):
    """수식어가 기존 글에 있는가 → 2(제목·키워드·소제목), 1(본문 2회 이상), 0(없음). 세부 질문이면 그 갈래의 다른 말이 소제목에 있어도 2."""
    head = re.sub(r"\s+", "", " ".join([art["title"], " ".join(art["keywords"]), " ".join(art["h2"])]).lower())
    if word in head:
        return 2
    if facet in FACET_HINTS and any(w in head for w in dict(FACETS)[facet] + FACET_HINTS[facet]):
        return 2      # 시점·뜻은 소제목 표현이 키워드와 달라도 알아본다('언제까지'·'공식과 용어')
    return 1 if re.sub(r"\s+", "", art["body"].lower()).count(word) >= (FACET_BODY_MIN if facet else 2) else 0

def compare(cand, art, corpus, demand=None):
    """후보 하나 ↔ 기존 글 하나 → (결정, 규칙, 이유, 신호). 신호에 변형 관계(variant_relation)와 확신(confidence)을 남긴다.
    관계: EQUIVALENT(표현만 다름) · SUBSUMED(그 글 범위 안) · DISTINCT_FACET(같은 주제, 다른 세부 질문) · ENTITY_VARIANT(도구만 다름)
          · FORMAT_VARIANT(형식 수식어만 다름) · UNKNOWN(모르는 수식어 — 자동으로 압축하지 않는다) · NONE(다른 주제).
    키워드만 있는 후보는 수식어마다 그 글에 실제로 있는지(제목·키워드·소제목·본문)를 본다 — 수식어 하나로 새 글·보강을 정하지 않는다."""
    an = corpus.an[art["id"]]
    bvec, tvec = cand["_vec"]
    best = max(an["cores"], key=lambda c: core_sim_fuzzy(cand["core"], c)) if cand["core"] else an["core"]
    cs = core_sim_fuzzy(cand["core"], best) if cand["core"] else 0.0
    tool_self = not cand["core"] and not an["core"] and bool(cand["pents"]) and cand["pents"] == an["pents"]
    ctype = next((c["type"] for c in corpus.cs if c["id"] == cand["cluster"]), "")
    # 도구 클러스터 안의 도구 이름 + 수식어('클로드 요금제 토큰')는 그 도구 글(core 없음)과 같은 주제 갈래다
    tool_family = (bool(cand["pents"]) and cand["pents"] == an["pents"] and cand["cluster"] == art["cluster"] and ctype == "tool"
                   and (not an["core"] or not cand["core"]))
    ce, ae = cand["entity"], an["ents"]
    ent = "same" if ce and ce == ae else "different" if ce and ae and not (ce & ae) else "overlap" if ce & ae else "none"
    words = list(dict.fromkeys(cand["core"]))
    cover = round(sum(1 for w in words if w in corpus.text[art["id"]]) / len(words), 3) if words else (1.0 if tool_self or tool_family else 0.0)
    sig = dict(cluster_match=cand["cluster"] == art["cluster"], intent_match=cand["intent"] == art["intent"], entity_match=ent,
               keyword_similarity=1.0 if tool_self or tool_family else cs, title_similarity=_cos(tvec, corpus.title[art["id"]]) if tvec else 0.0,
               topic_similarity=_cos(bvec, corpus.body[art["id"]]) if bvec else None, coverage=cover,
               keyword_exact=False, core=f"{'·'.join(cand['core']) or '(도구 자체)'} ↔ {'·'.join(an['core']) or '(도구 자체)'}",
               facets=f"{'·'.join(FACET_KO.get(f, f) for f in sorted(cand['fams'])) or '—'} ↔ {'·'.join(FACET_KO.get(f, f) for f in sorted(an['fams'])) or '—'}",
               facet=",".join(sorted(cand["fams"] - {"AI"})) or "", variant_relation="NONE", confidence="HIGH", modifiers=[],
               entity_conflict=cand.get("conflict") or [])
    topic_hi = (sig["topic_similarity"] or 0) >= T_BODY if cand["body"] else cover >= T_COVER
    same_topic = tool_self or tool_family or cs >= CORE_NEAR
    shared = (cand["fams"] & an["fams"]) - {"AI"}
    sig["score"] = round(0.1 * sig["cluster_match"] + 0.1 * sig["intent_match"] + 0.1 * (ent in ("same", "overlap"))
                         + 0.35 * sig["keyword_similarity"] + 0.1 * sig["title_similarity"]
                         + 0.25 * (min(1.0, sig["topic_similarity"] / 0.3) if sig["topic_similarity"] is not None else cover), 3)
    a_ref = f"{art['id']}({art['title'][:30]})"
    def out(d, rule, why, rel, conf):
        sig["variant_relation"], sig["confidence"] = rel, conf
        if sig["entity_conflict"]:   # '구글 챗GPT'처럼 회사·도구가 엇갈리면 자동으로 정하지 않는다
            why += f" — 회사·도구가 엇갈린다({', '.join(sig['entity_conflict'])}): 확인 필요"
            if d == "REJECT":
                d, rule = "UPDATE_EXISTING", rule + "/entity_conflict"
            conf = sig["confidence"] = "LOW"
        return d, rule, why, sig
    cq = canon(cand["keyword"], corpus.es)
    sig["keyword_exact"] = cq in an["canon"] and bool(cq[0] or cq[2])
    if sig["keyword_exact"]:   # 표준형(주제 핵심·질문어·도구)이 같다 — 표현만 다른 같은 검색어(주제 판정보다 먼저 본다)
        extra = [w for w in words if w not in corpus.text[art["id"]]]
        if not extra:
            return out("REJECT", "R1_같은검색어", f"{a_ref}이 같은 검색어·같은 세부 질문({sig['facets']})으로 이미 답한다 — 새로 쓰거나 보강할 몫이 없다", "EQUIVALENT", "HIGH")
        return out("UPDATE_EXISTING", "U1_거의같음", f"{a_ref}과 검색 요구가 거의 같다 — 빠진 말({'·'.join(extra[:4])})만 그 글에 보강", "EQUIVALENT", "MEDIUM")
    if not same_topic:
        why = (f"같은 클러스터·같은 의도여도 주제 핵심이 다르다({sig['core']}) — 별도 글" if sig["cluster_match"] and sig["intent_match"]
               else f"주제 핵심이 다르다({sig['core']})")
        return out("CREATE_NEW", "N1_다른주제", why, "NONE", "HIGH")
    if ent == "different":       # 같은 과업, 다른 도구 — 이름만 바꾼 글인지, 도구별 수요가 따로 있는지
        dm = demand_state(demand)
        sig["demand"] = dm
        if dm == "CONFIRMED":
            return out("CREATE_NEW", "N2_도구별수요", f"과업이 같고 도구만 다르지만({'·'.join(ce)} ↔ {'·'.join(ae)}) 독립 검색 수요가 확인됐다(CONFIRMED) — 도구별 절차·기능 차이를 쓰는 새 글",
                       "ENTITY_VARIANT", "MEDIUM")
        mention = any(re.search(e["rx"], art["body"]) for e in corpus.es if e["name"] in ce)
        return out("UPDATE_EXISTING", "U2_도구만다름", (f"과업이 같고 도구만 다르다({'·'.join(ce)} ↔ {'·'.join(ae)}), 수요 {dm}. "
            + (f"{a_ref}이 이미 {'·'.join(ce)}를 언급한다" if mention else f"{a_ref}에 {'·'.join(ce)} 절을 더하는 보강 후보")
            + " — 독립 수요가 CONFIRMED되면 CREATE_NEW"), "ENTITY_VARIANT", "MEDIUM" if mention else "LOW")
    if cand["body"]:            # 원고끼리: 실제 본문 겹침이 증거다
        if shared and topic_hi:
            return out("UPDATE_EXISTING", "U3_같은갈래", f"같은 주제({sig['core']})의 같은 세부 질문({'·'.join(FACET_KO.get(f, f) for f in sorted(shared))})을 {a_ref}이 다루고, 본문 유사도 {sig['topic_similarity']} — 새 글 대신 그 글 보강",
                       "SUBSUMED", "HIGH")
        if shared:
            return out("CREATE_NEW", "N3_갈래만겹침", f"같은 주제·같은 세부 질문({'·'.join(FACET_KO.get(f, f) for f in sorted(shared))})이지만 내용 겹침이 낮다 — 새 글로 쓰되 {a_ref}과 서로 링크",
                       "DISTINCT_FACET", "MEDIUM")
        return out("CREATE_NEW", "N4_다른질문", f"같은 주제의 다른 세부 질문({sig['facets']}) — 새 글, {a_ref}과 서로 링크", "DISTINCT_FACET", "HIGH")
    # 키워드만 있는 후보: 그 글에 없는 말(수식어)마다 실제 커버리지를 본다
    art_core = "".join(t for c in an["cores"] for t in c)
    mods = [("core", w, None) for w in words if w not in art_core and not any(_tok_match(w, t) for c in an["cores"] for t in c)]
    # 후보가 그 글보다 넓다 — 가장 가까운 키워드에 후보에 없는 주제어가 있다('종합소득세 계산' ↔ '종합소득세 중간예납'). 범위 안이 아니다
    broader = [t for t in best if t not in SCOPE_WORDS and not any(_tok_match(t, w) for w in words)] if words else []
    # 질문어 단위로 본다: 그 글 키워드에 같은 질문어가 있거나, 바꿔 써도 되는 갈래가 그 글 키워드에 있으면 덮인 것
    years = {w for w in cand["fw"] if re.fullmatch(r"20\d\d", w)}
    art_years = {w for w in an["fw"] if re.fullmatch(r"20\d\d", w)}
    mods += [("facet", w, _facet_of(w) or "deadline") for w in sorted(cand["fw"])
             if (_facet_of(w) or w in years) and _facet_of(w) != "AI" and w not in an["fw"]
             and not (_facet_of(w) in INTERCHANGEABLE and _facet_of(w) in an["fams"])]
    cov = {m: _cover(m[1], art, m[2]) for m in mods}
    for m in mods:   # 연도가 다른 판('26년 최저임금' ↔ '최저임금 2027')은 본문에 그해가 나와도 다른 질문이다
        if m[1] in years and art_years and m[1] not in art_years:
            cov[m] = 0
    sig["modifiers"] = [f"{m[1]}({FACET_KO.get(m[2], m[2]) if m[2] else '수식어'}:{cov[m]})" for m in mods]
    uncov = [m for m in mods if cov[m] == 0]
    if broader and not [m for m in mods if m[0] == "core"]:
        return out("CREATE_NEW", "N7_후보가더넓음", f"{a_ref}은 더 좁은 주제({'·'.join(best)})를 다룬다 — 후보('{cand['keyword']}')의 넓은 질문은 그 글 범위 밖, 새 글로 쓰고 서로 링크",
                   "DISTINCT_FACET", "MEDIUM")
    if not mods or not uncov:
        # 확신 HIGH는 그 글의 메인 키워드나 소제목이 후보를 직접 덮을 때만. 보조 키워드로만 덮이거나, 그 글이 후보보다 좁으면('알바 4대보험' ↔ '4대보험 가입조건') MEDIUM
        narrower = [t for t in best if t not in SCOPE_WORDS and t not in "".join(cand["core"])]
        direct = (cand["fams"] - {"AI"}) <= an["pfams"] or (mods and all(v == 2 for v in cov.values()))
        # HIGH는 그 글의 메인 키워드가 후보를 덮을 때만 — 보조 키워드('포스터 만들기')로만 덮이면 MEDIUM
        conf = "HIGH" if direct and all(v == 2 for v in cov.values()) and not narrower and best == an["core"] else "MEDIUM"
        # 세부 질문이 본문에만 나오면(소제목·제목·키워드엔 없음) 우연한 언급일 수 있다 — 보강 쪽 판정은 두되 확신 LOW(어느 모드에서도 빼지 않음)
        if any(m[2] and cov[m] == 1 for m in mods):
            conf = "LOW"
        if narrower:
            sig["modifiers"].append(f"그 글이 더 좁다({'·'.join(narrower)})")
        why = (f"그 글의 범위 안이다 — " + (f"수식어 {', '.join(sig['modifiers'])}가 {a_ref}에 이미 있다" if mods else f"{a_ref}의 키워드·세부 질문이 후보를 품는다")
               + " — 새 글 대신 그 글 보강")
        return out("UPDATE_EXISTING", "U5_범위안", why, "SUBSUMED", conf)
    if all(m[2] == FORMAT_FACET for m in uncov):
        return out("UPDATE_EXISTING", "U6_형식만다름", f"형식 수식어({', '.join(m[1] for m in uncov)})만 다르다 — 같은 요구를 다른 꼴로 묻는다, {a_ref}에 그 꼴(양식·예시)을 더하는 보강 후보",
                   "FORMAT_VARIANT", "MEDIUM")
    distinct = [m for m in uncov if m[2] and m[2] != FORMAT_FACET]
    if distinct:
        return out("CREATE_NEW", "N5_다른세부질문", f"같은 주제지만 {a_ref}에 없는 세부 질문({', '.join(f'{m[1]}={FACET_KO[m[2]]}' for m in distinct)}) — 새 글, 서로 링크",
                   "DISTINCT_FACET", "HIGH" if not shared else "MEDIUM")
    strong = cs >= 0.75     # 주제어가 거의 같을 때만 보강 쪽으로(확신 LOW라 어느 모드에서도 빼지 않는다). 도구 이름만 같으면 새 글 쪽
    return out("UPDATE_EXISTING" if strong else "CREATE_NEW", "U7_모르는수식어" if strong else "N6_모르는수식어",
               f"{a_ref}에 없는 수식어({', '.join(m[1] for m in uncov)})의 뜻을 판정하지 못했다 — "
               + ("주제가 거의 같아 보강 쪽으로 두되 자동으로 빼지 않는다" if strong else "자동으로 압축하지 않는다"), "UNKNOWN", "LOW")

SEVERITY = {d: i for i, d in enumerate(DECISIONS)}   # CREATE_NEW 0 < UPDATE_EXISTING 1 < REJECT 2

def _cand_of(a, corpus):
    return candidate(a["keywords"][0], corpus.cs, corpus.es, a["keywords"], a["title"], a["body"], a["intent"], a["cluster"], a["entity"])

def decide(cand, corpus, exclude=(), demand=None):
    """후보 → 판정 기록. 고르는 순서(점수 하나로 합치지 않는다):
      1) 생애주기 권한 — 검색 자산(published·scheduled)이 낸 UPDATE_EXISTING·REJECT가 있으면 그중에서 고른다
      2) 결정의 무게 — REJECT > UPDATE_EXISTING
      3) 신호 — score
    검색 자산이 모두 CREATE_NEW이면 원고(draft)를 본다. 원고는 REJECT를 못 내고 UPDATE_EXISTING(review_draft)이 되며,
    원고 둘 이상이 후보와 겹치고 서로도 겹치면 consolidate_drafts다. 권한 0인 글은 history로만 남는다."""
    demand = demand_state(demand)
    cand["_vec"] = corpus.vec(cand["body"], cand["title"])
    entries, history = [], []
    for a in corpus.arts:
        if a["id"] in exclude:
            continue
        raw, rule, why, sig = compare(cand, a, corpus, demand)
        auth = AUTHORITY.get(a["status"], 0)
        e = dict(a=a, auth=auth, raw=raw, decision=raw, rule=rule, why=why, sig=sig)
        if auth == 0:
            if raw != "CREATE_NEW":
                history.append(dict(id=a["id"], status=a["status"] or "(없음)", would_be=raw, rule=rule))
            continue
        if auth == 1 and raw == "REJECT":   # 원고는 검색 자산이 아니다 — 후보를 막지 못한다
            e["decision"] = "UPDATE_EXISTING"
        entries.append(e)
    # 같은 도구의 자기 글이 같은 주제로 있으면, 다른 도구 글과의 '도구만 다름(U2)'은 판정 근거가 아니다
    # ('배민 수수료 인상'이 39편 배민 수수료를 두고 73편 쿠팡이츠 원고로 가던 것, 2026-10-08 큐 실측)
    if any(e["sig"]["entity_match"] in ("same", "overlap") and e["sig"]["keyword_similarity"] >= CORE_NEAR for e in entries):
        for e in entries:
            if e["rule"] == "U2_도구만다름":
                e["decision"] = "CREATE_NEW"
    key = lambda e: (SEVERITY[e["decision"]], SEVERITY[e["raw"]], e["sig"]["score"])
    firm = sorted([e for e in entries if e["auth"] == 2 and e["decision"] != "CREATE_NEW"], key=key, reverse=True)
    soft = sorted([e for e in entries if e["auth"] == 1 and e["decision"] != "CREATE_NEW"], key=key, reverse=True)
    related = [dict(id=e["a"]["id"], status=e["a"]["status"], decision=e["decision"], score=e["sig"]["score"])
               for e in sorted(entries, key=lambda e: e["sig"]["score"], reverse=True)
               if (e["decision"] != "CREATE_NEW" or e["sig"]["cluster_match"] or e["sig"]["keyword_similarity"] >= CORE_NEAR) and e["sig"]["score"] >= 0.3][:5]
    drafts = [dict(id=e["a"]["id"], would_be=e["raw"], rule=e["rule"]) for e in soft]
    if firm:
        top = firm[0]
        action = "reject_duplicate" if top["decision"] == "REJECT" else "update_published"
        selection = f"검색 자산({top['a']['status']})의 {top['decision']}을 골랐다(권한 2 > 원고 1)"
        if soft:
            selection += f" — 같은 요구를 점유한 원고 {len(soft)}편도 함께 검토: " + ", ".join(f"{d['id'][:20]}({d['would_be']})" for d in drafts[:3])
        why = top["why"]
    elif soft:
        top = soft[0]
        # 원고끼리 같은 주제를 점유하는가 — 후보가 걸린 원고를 다른 원고 전부와 본문으로 견준다(파일은 고치지 않는다).
        # 후보가 두 원고에 똑같이 걸리지 않아도(한쪽은 '후보가 더 넓음' 등) 원고 둘이 겹치면 정리 대상이다
        clash = []
        cx = _cand_of(top["a"], corpus); cx["_vec"] = corpus.vec(cx["body"], cx["title"])
        for y in corpus.arts:
            if y["id"] != top["a"]["id"] and AUTHORITY.get(y["status"], 0) == 1 and compare(cx, y, corpus, "CONFIRMED")[0] != "CREATE_NEW":
                clash.append((top["a"]["id"], y["id"]))
        drafts += [dict(id=b, would_be="(원고끼리 겹침)", rule="consolidate") for _, b in clash if b not in {d["id"] for d in drafts}]
        action = "consolidate_drafts" if clash else "review_draft"
        selection = "검색 자산 중 겹치는 글이 없고 원고만 겹친다 — 원고는 REJECT를 못 내므로 UPDATE_EXISTING"
        if top["raw"] == "REJECT":
            selection += f"(원래는 {top['raw']}: {top['rule']})"
        why = top["why"] + (" — 새 원고를 만들기 전에 이 원고들을 하나로 정리할지 검토: " + ", ".join(f"{a}↔{b}" for a, b in clash[:3]) if clash
                            else " — 새 원고를 만들기 전에 이 원고를 다시 쓰거나·정리하거나·버릴지 검토")
        if top["a"]["status"] == "hold":
            why += " (이 원고는 hold — 발행 전 검토가 필요한 기존 글이다. 새 원고 대신 이 글의 검토를 마치고 보강·발행할지 정한다)"
    else:
        top = None
    if top is None:
        near = max(entries, key=lambda e: e["sig"]["score"], default=None)
        if not near or (near["rule"] == "N1_다른주제" and not near["sig"]["cluster_match"]):
            rec = dict(decision="CREATE_NEW", rule="N0_관련글없음", reason="견줄 만한 기존 글이 없다", matched_article=None, signals=None,
                       matched_status=None, action="create_new", selection="검색 자산·원고 모두 CREATE_NEW")
        else:
            rec = dict(decision="CREATE_NEW", rule=near["rule"], reason=near["why"], signals=near["sig"], matched_status=near["a"]["status"],
                       action="create_new", selection="검색 자산·원고 모두 CREATE_NEW — 가장 가까운 글을 근거로 보인다",
                       matched_article=_art_ref(near["a"]))
    else:
        rec = dict(decision=top["decision"], rule=top["rule"], reason=why, signals=top["sig"], matched_status=top["a"]["status"],
                   action=action, selection=selection, matched_article=_art_ref(top["a"]))
    sg = rec.get("signals") or {}
    rec.update(variant_relation=sg.get("variant_relation", "NONE"), confidence=sg.get("confidence", "HIGH"),
               candidate=dict(keyword=cand["keyword"], cluster=cand["cluster"], intent=cand["intent"], entity=sorted(cand["entity"]),
                              facet=",".join(sorted(cand["fams"] - {"AI"}))),
               demand=demand, related=related, drafts=drafts, history=history,
               considered=[dict(id=e["a"]["id"], status=e["a"]["status"], authority=e["auth"], raw=e["raw"], decision=e["decision"], rule=e["rule"], score=e["sig"]["score"])
                           for e in (firm + soft)[:6]])
    return rec

def _art_ref(a):
    return dict(id=a["id"], title=a["title"], status=a["status"], status_source=a.get("status_source", "frontmatter"),
                cluster=a["cluster"], intent=a["intent"], entity=a["entity"])

def decide_file(path, corpus=None, demand="CONFIRMED"):
    """볼트 원고 하나를 나머지 네이버 글 전부와 견준다. 원고는 STEP 0(자동완성 검증)을 거쳤으므로 수요는 CONFIRMED로 본다
    — 파일만으로는 증명할 수 없는 가정이다(STEP 0을 건너뛴 원고는 도구만 다른 경우 너그럽게 판정된다)."""
    cs, es = (corpus.cs, corpus.es) if corpus else (load_clusters(), load_entities())
    corpus = corpus or Corpus(load_articles(), cs, es)
    me = next(a for a in load_articles([path]))
    if not me["keywords"]:
        return None
    cand = candidate(me["keywords"][0], cs, es, me["keywords"], me["title"], me["body"], me["intent"], me["cluster"], me["entity"])
    return decide(cand, corpus, exclude={me["id"]}, demand=demand)

SIG_KEYS = ("cluster_match", "intent_match", "entity_match", "keyword_similarity", "keyword_exact", "title_similarity", "topic_similarity", "coverage",
            "variant_relation", "confidence")

def update_record(rec, day=None):
    """UPDATE_EXISTING 판정 → 보강 인계 한 줄. 검색 자산 보강(update_published)은 주 3건 상한(SKILL '발행본 보강')을 따르고,
    원고 검토(review_draft·consolidate_drafts)는 그 상한과 별개다 — 행동(action) 열로 가른다."""
    s = rec["signals"]
    sig = json.dumps({k: s.get(k) for k in SIG_KEYS}, ensure_ascii=False)
    return (day or datetime.date.today().isoformat(), rec["matched_article"]["id"], rec["matched_status"], rec["action"],
            rec["candidate"]["keyword"], rec["rule"], rec["reason"], sig)

def append_updates(recs, path=None):
    """보강 인계 파일에 UPDATE_EXISTING만 덧붙인다(같은 글·같은 키워드는 한 번). 원고는 고치지 않는다."""
    path = path or UPDATE_F
    have = set()
    if os.path.exists(path):
        have = {(r[1], r[4]) for r in _rows(path, 7)}
    new = []
    for r in recs:
        key = (r["matched_article"]["id"], r["candidate"]["keyword"]) if r["decision"] == "UPDATE_EXISTING" else None
        if key and key not in have:
            have.add(key)
            new.append(update_record(r))
    if not new:
        return 0
    first = not os.path.exists(path)
    with io.open(path, "a", encoding="utf-8") as f:
        if first:
            f.write("# 보강 인계 — blog_taxonomy.py decide 의 UPDATE_EXISTING. update_published는 주간 분석이 주 3건 이하를 골라 원고를 고치고 analytics/발행본-수정대기.md 로 올린다.\n")
            f.write("# review_draft·consolidate_drafts는 원고 검토 — 발행 글 수정 상한과 별개. 형식: 날짜<TAB>기존 글<TAB>그 글 상태<TAB>행동<TAB>후보 키워드<TAB>규칙<TAB>이유<TAB>신호(JSON). 이 파일은 원고를 고치지 않는다\n")
        for r in new:
            f.write("\t".join(r) + "\n")
    return len(new)

def explain(rec):
    c = rec["candidate"]
    lines = [f"decision: {rec['decision']}  ({rec['rule']})  action={rec['action']}  relation={rec['variant_relation']}  confidence={rec['confidence']}",
             f"candidate: {c['keyword']}  [{c['cluster'] or '—'} · {c['intent']} · facet {c['facet'] or '—'} · {', '.join(c['entity']) or '—'}]  demand={rec['demand']}"]
    if rec["matched_article"]:
        a, s = rec["matched_article"], rec["signals"]
        lines.append(f"matched_article: {a['id']} — {a['title']}  [matched_status={rec['matched_status']} · {a['cluster']} · {a['intent']}]")
        lines.append("signals: " + ", ".join(f"{k}={s.get(k)}" for k in SIG_KEYS + ("score",)))
        lines.append(f"  core {s['core']} · facets {s['facets']}" + (f" · modifiers {', '.join(s['modifiers'])}" if s.get("modifiers") else "")
                     + (f" · entity_conflict {', '.join(s['entity_conflict'])}" if s.get("entity_conflict") else ""))
    lines.append(f"selection: {rec['selection']}")
    lines.append(f"reason: {rec['reason']}")
    if rec["considered"]:
        lines.append("considered: " + " | ".join(f"{x['id'][:18]}[{x['status']}·권한{x['authority']}] {x['raw']}" + (f"→{x['decision']}" if x["raw"] != x["decision"] else "") for x in rec["considered"]))
    if rec["history"]:
        lines.append("history(권한 없음, 판정에 쓰지 않음): " + ", ".join(f"{h['id'][:18]}[{h['status']}] {h['would_be']}" for h in rec["history"]))
    if rec["related"]:
        lines.append("related: " + " | ".join(f"{r['id'][:20]}({r['status']}·{r['decision']}, {r['score']})" for r in rec["related"]))
    return "\n".join(lines)


# ───────────────────────── 내부 링크 (Phase 5, 2026-10-08) ─────────────────────────
# 목표는 링크 수가 아니라 '이 글을 읽은 사람이 다음에 궁금해할 질문'을 잇는 것이다. 판정 엔진의 변형 관계(compare)를 그대로 쓴다.
#   P1 같은 클러스터 + 다른 세부 질문(DISTINCT_FACET) — 가장 먼저
#   P2 같은 클러스터 + 보완 관계 의도(판정→방법, 뜻→계산 …) + 본문 관련도
#   P3 같은 클러스터 + 도구만 다름(ENTITY_VARIANT) — 비교·선택 맥락이 있을 때만
#   P4 같은 레인 + 높은 본문 관련도
#   P5 다른 레인 + 문맥 근거(이 글 본문이 그 글의 주제를 실제로 말한다)
# 빼는 것: EQUIVALENT(링크보다 중복 검토) · SUBSUMED(정리 맥락) · UNKNOWN(자동 추천 안 함) · 같은 레인만 · 같은 도구만 · 낱말 하나 겹침 · 맥락 없는 제휴 글.
# 링크 대상은 실제 검색 자산(실효 published)만. 원고는 future_link_candidate로만 보인다. 실제 원고·발행 글은 고치지 않는다.
# 보정값 — 2026-10-08 발행 74편의 쌍에서 사람이 실제로 건 링크와 안 건 쌍의 본문 유사도를 재서 정했다(재측정 TODO는 CALIBRATION과 같다)
LINK_CAL = dict(measured="2026-10-08", same_lane_linked_median=0.073, same_lane_unlinked_p95=0.089, cross_lane_linked_median=0.056, cross_lane_unlinked_p95=0.049)
LINK_T_LANE = 0.08     # 같은 레인: 링크 안 한 쌍의 p95와 링크한 쌍의 중앙값 사이
LINK_T_CROSS = 0.06    # 다른 레인: 같은 방식 — 여기에 문맥 근거가 더 있어야 한다
LINK_MAX = 3           # 한 글에 추천하는 최대 수(채우지 않는다)
# 읽는 순서(앞 → 뒤로 이어진다): 뜻 → 대상·의무 → 계산·가격·비교 → 신청·방법·양식 → 기한 → 문제
FACET_STAGE = {"meaning": 1, "eligibility": 2, "requirement": 2, "calculation": 3, "price": 3, "limit": 3, "billing": 3, "comparison": 3,
               "recommendation": 3, "application": 4, "how_to": 4, "document": 4, "deadline": 5, "problem": 6}
INTENT_STAGE = {"뜻": 1, "판정": 2, "계산": 3, "비교": 3, "방법": 4, "문구": 4, "문제해결": 5}
# 앵커 제안 — 대상 글 메인 키워드에 '다음 질문' 꼬리를 붙인다(키워드만 그대로 쓰지 않는다). 키워드에 이미 그 갈래의 말이 있으면 '정리'만.
# 조사가 붙지 않는 명사구로 쓴다. 실제 삽입은 사람이 문장 안에서 고친다
ANCHOR = {"meaning": "뜻 정리", "calculation": "계산 예시", "price": "비용 정리", "billing": "결제·해지 정리", "limit": "무료 범위", "eligibility": "기준 정리",
          "requirement": "의무와 불이익", "deadline": "기한 정리", "document": "예시 모음", "problem": "해결 순서", "comparison": "비교 정리",
          "recommendation": "고르는 기준", "application": "신청 절차", "how_to": "순서 정리"}

def lognos_in(body):
    return set(re.findall(r"blog\.naver\.com/(?:thomasai/|PostView\.naver\?blogId=thomasai&(?:amp;)?logNo=)(\d{9,})", body))

def logno_of(a):
    m = re.search(r"/(\d{9,})", a["meta"].get("url", "") or "")
    return m.group(1) if m else ""

def _primary_facet(fams, intent):
    f = sorted(fams - {"AI"}, key=lambda x: FACET_STAGE.get(x, 9))
    return f[0] if f else INTENT_FACET.get(intent, "")

def _lane(corpus, cid):
    return next((c["lane"] for c in corpus.cs if c["id"] == cid), "")

def _target_facet(an, intent):
    """대상 글의 대표 질문 — 메인 키워드의 갈래가 먼저, 연도만으로 붙은 '기한'은 빼고, 없으면 intent"""
    f = an["pfams"] - ({"deadline"} if not (an["fw"] - {w for w in an["fw"] if re.fullmatch(r"20\d\d", w)}) & set(dict(FACETS)["deadline"]) else set())
    return _primary_facet(f, intent) if f else INTENT_FACET.get(intent, "")

def _anchor(t, corpus):
    an = corpus.an[t["id"]]
    kw = t["keywords"][0] if t["keywords"] else t["title"]
    f = _target_facet(an, t["intent"])
    has = any(w in re.sub(r"\s+", "", kw.lower()) for w in dict(FACETS).get(f, ()))
    return f"{kw} {'정리' if has or f not in ANCHOR else ANCHOR[f]}"

def link_candidates(src, corpus, max_n=LINK_MAX):
    """src(볼트 원고 dict 또는 candidate()로 만든 키워드 후보) → dict(recommended, already_linked, excluded, future).
    recommended는 많아야 max_n개 — 맞는 글이 없으면 0개다."""
    is_art = "path" in src
    cand = _cand_of(src, corpus) if is_art else dict(src)
    cand["_vec"] = corpus.vec(cand["body"], cand["title"])
    sid = src.get("id", "")
    have = lognos_in(src["body"]) if is_art else set()
    s_lane, s_fac = _lane(corpus, cand["cluster"]), _primary_facet(cand["fams"], cand["intent"])
    s_text = re.sub(r"\s+", "", (src.get("body") or "").lower())
    rows = []
    for t in corpus.arts:
        if t["id"] == sid:
            continue
        d, rule, why, sig = compare(cand, t, corpus, "CONFIRMED")
        an = corpus.an[t["id"]]
        rel, sc = sig["variant_relation"], sig["cluster_match"]
        same_lane = s_lane and s_lane == _lane(corpus, t["cluster"])
        ts = sig["topic_similarity"] if sig["topic_similarity"] is not None else (sig["coverage"] * 0.1)
        t_fac = _target_facet(an, t["intent"])
        si, ti = INTENT_STAGE.get(cand["intent"], 0), INTENT_STAGE.get(t["intent"], 0)
        complementary = bool(si and ti and si != ti)
        t_core = "".join(an["core"])
        # 문맥 근거: 그 글의 주제어가 이 글 소제목에 나오거나 본문에 3번 이상 — 한 글자·두 글자 일반어('리뷰'·'네이버')는 소제목에 있을 때만
        s_head = re.sub(r"\s+", "", " ".join(src.get("h2") or []).lower())
        context = bool(t_core) and (t_core in s_head or (len(t_core) >= 3 and s_text.count(t_core) >= 3))
        affiliate = bool(t["meta"].get("affiliate")) or _lane(corpus, t["cluster"]) == "장비"
        pr, why_l, drop = None, "", None
        if rel == "EQUIVALENT":
            drop = "cannibalization_review — 같은 검색 요구라 링크보다 중복 검토"
        elif rel == "SUBSUMED":
            drop = "consolidation_context — 한쪽이 다른 쪽 범위 안(보강·정리 맥락)"
        elif rel == "UNKNOWN":
            drop = "unknown — 관계를 판정하지 못해 자동 추천하지 않음"
        elif sc and rel == "DISTINCT_FACET":
            pr, why_l = 1, f"같은 주제의 다른 질문({FACET_KO.get(s_fac, s_fac)} → {FACET_KO.get(t_fac, t_fac)}) — 이어서 궁금해할 질문"
        elif sc and rel == "ENTITY_VARIANT":
            comp = {"comparison", "recommendation", "price", "limit"} & (cand["fams"] | an["fams"]) or "비교" in (cand["intent"], t["intent"])
            if comp:
                pr, why_l = 3, f"같은 일을 다른 도구로({'·'.join(sorted(cand['entity'])) or '—'} ↔ {'·'.join(sorted(an['ents']))}) — 고르는 맥락"
            else:
                drop = "entity_only — 도구만 다르고 비교·선택 맥락이 없음"
        elif sc and complementary and ts >= LINK_T_LANE:
            pr, why_l = 2, f"같은 클러스터, 보완 관계 의도({cand['intent']} → {t['intent']}), 본문 관련도 {ts}"
        elif not sc and same_lane and sig["entity_match"] == "different" and not context:
            drop = "different_tool — 클러스터도 도구도 다르다(같은 레인일 뿐)"
        elif not sc and same_lane and ts >= LINK_T_LANE and (context or sig["keyword_similarity"] > 0):
            pr, why_l = 4, f"같은 레인 업무 흐름, 본문 관련도 {ts}" + (" — 이 글이 그 주제를 직접 말한다" if context else "")
        elif not same_lane and ts >= LINK_T_CROSS and context:
            pr, why_l = 5, f"다른 레인이지만 이 글 본문이 '{' '.join(an['core'])}'를 직접 다룬다(본문 관련도 {ts})"
        else:
            drop = ("same_entity_only" if sig["entity_match"] in ("same", "overlap") else "same_lane_only" if same_lane else "weak") + f" — 근거 부족(본문 관련도 {ts})"
        if pr and affiliate and pr in (4,) and not context:
            pr, drop = None, "affiliate_irrelevant — 맥락 없는 제휴·장비 글"
        if not pr:
            if drop and (sc or ts >= LINK_T_CROSS):
                rows.append(dict(target=t, drop=drop, sig=sig))
            continue
        # 방향: 읽는 순서 앞 → 뒤가 기본. 인접하거나 '뜻'이 끼면 양방향, 도구 변형은 양방향, 문맥 링크는 이 글 → 그 글만
        if pr in (1, 2):
            a_st = FACET_STAGE.get(s_fac, 4) if pr == 1 else si
            b_st = FACET_STAGE.get(t_fac, 4) if pr == 1 else ti
            # 읽는 순서 앞 → 뒤가 기본. 단계가 가깝거나(2 이하) '뜻'이 끼면 양방향 — 세부 글에서 기초로 돌아가는 링크도 자연스럽다
            direction = "bidirectional" if "meaning" in (s_fac, t_fac) or abs(a_st - b_st) <= 2 else ("A→B" if a_st < b_st else "B→A")
        elif pr == 3:
            direction = "bidirectional"
        elif pr == 4:
            direction = "bidirectional" if ts >= 2 * LINK_T_LANE else "A→B"
        else:
            direction = "A→B"
        score = round(min(1.0, {1: 0.9, 2: 0.75, 3: 0.6, 4: 0.55, 5: 0.45}[pr] + 0.1 * min(1.0, ts / 0.3) + (0.05 if complementary else 0)), 3)
        rows.append(dict(target=t, priority=pr, direction=direction, score=score, reason=why_l, sig=sig,
                         already=logno_of(t) in have if logno_of(t) else False))
    live = [r for r in rows if r.get("priority") and r["target"]["status"] == "published" and r["direction"] in ("A→B", "bidirectional")]
    live.sort(key=lambda r: (r["priority"], -r["score"]))
    rec = [r for r in live if not r["already"]][:max_n]
    fmt = lambda r: dict(source=sid or cand["keyword"], source_cluster=cand["cluster"], source_facet=s_fac,
                         target=r["target"]["id"], target_title=r["target"]["title"], target_cluster=r["target"]["cluster"],
                         target_facet=_target_facet(corpus.an[r["target"]["id"]], r["target"]["intent"]),
                         target_url=r["target"]["meta"].get("url", ""), target_status=r["target"]["status"],
                         relationship=dict(priority=r.get("priority"), variant=r["sig"]["variant_relation"], cluster="same" if r["sig"]["cluster_match"] else "different",
                                           intent=f"{cand['intent']}→{r['target']['intent']}", entity=r["sig"]["entity_match"]),
                         direction=r.get("direction"), score=r.get("score"), reason=r.get("reason") or r.get("drop"),
                         already_linked=r.get("already", False), suggested_anchor=_anchor(r["target"], corpus) if r.get("priority") else "")
    return dict(recommended=[fmt(r) for r in rec],
                already_linked=[fmt(r) for r in live if r["already"]],
                reverse_only=[fmt(r) for r in rows if r.get("priority") and r["target"]["status"] == "published" and r["direction"] == "B→A"],
                future=[fmt(r) for r in rows if r.get("priority") and r["target"]["status"] != "published"],
                excluded=[fmt(r) for r in rows if not r.get("priority")])

def _is_affiliate(a):
    return "/제휴/" in a["path"].replace(os.sep, "/") or bool(a["meta"].get("affiliate"))

def affiliate_bridge(art, corpus, story=""):
    """제휴 글 → 그 글로 이어지는 **발행된 일반 글**(Affiliate Phase 2, 2026-10-08). 링크 엔진의 P1/P2는 같은 클러스터를 요구하는데
    장비 클러스터(eq-*)의 글은 모두 제휴 글이라 제휴 글에는 구조상 0이다 — 그래서 레인을 넘는 다리를 따로 센다:
      story  — 재고 story 끝 괄호의 편 번호('… (25편 통화녹음)')가 가리키는 일반 글
      linked — 이 글 본문이 이미 거는 일반 글('함께 보면 좋은 글')
      topic  — 본문 관련도 LINK_T_CROSS 이상 + 문맥 근거(어느 한쪽 글이 다른 쪽 주제어를 소제목에 쓰거나 본문에 3번 이상)
    READY 조건은 아니다(강력 권장). 판정·추천 링크는 바꾸지 않는다."""
    gen = [t for t in corpus.arts if not _is_affiliate(t) and t["status"] == "published" and t["id"] != art["id"]]
    nums = {int(n) for n in re.findall(r"(\d+)편", story or "")}
    story_ids = [t["id"] for t in gen if (m := re.match(r"(\d+)편", t["id"])) and int(m.group(1)) in nums]
    have = lognos_in(art["body"])
    linked = [t["id"] for t in gen if logno_of(t) and logno_of(t) in have]
    cand = _cand_of(art, corpus)
    cand["_vec"] = corpus.vec(cand["body"], cand["title"])
    a_core = "".join(cand["core"])
    a_head = re.sub(r"\s+", "", " ".join(art.get("h2") or []).lower())
    a_text = re.sub(r"\s+", "", (art.get("body") or "").lower())
    topic = []
    for t in gen:
        _, _, _, sig = compare(cand, t, corpus, "CONFIRMED")
        ts = sig["topic_similarity"] or 0
        if ts < LINK_T_CROSS:
            continue
        t_core = "".join(corpus.an[t["id"]]["core"])
        t_head = re.sub(r"\s+", "", " ".join(t.get("h2") or []).lower())
        t_text = re.sub(r"\s+", "", (t.get("body") or "").lower())
        fwd = bool(t_core) and (t_core in a_head or (len(t_core) >= 3 and a_text.count(t_core) >= 3))
        rev = bool(a_core) and (a_core in t_head or (len(a_core) >= 3 and t_text.count(a_core) >= 3))
        if fwd or rev:
            topic.append((t["id"], round(ts, 3)))
    topic.sort(key=lambda x: -x[1])
    ids = sorted(set(story_ids) | set(linked) | {i for i, _ in topic})
    return dict(story=story_ids, linked=linked, topic=topic, bridges=ids, count=len(ids))

def link_graph(corpus):
    """실효 published 글 사이의 내부 링크 그래프 — 볼트 원고 본문 기준(발행 때 손으로 고친 링크와 다를 수 있다)."""
    pub = [a for a in corpus.arts if a["status"] == "published"]
    by_ln = {logno_of(a): a["id"] for a in corpus.arts if logno_of(a)}
    out, inn = {a["id"]: set() for a in pub}, {a["id"]: set() for a in pub}
    for a in pub:
        for x in lognos_in(a["body"]):
            b = by_ln.get(x)
            if b and b != a["id"] and b in inn:
                out[a["id"]].add(b); inn[b].add(a["id"])
    return pub, out, inn

def legacy_link_candidates(a, corpus):
    """kw_pipeline check의 레거시 '내부 링크 후보' — 메인 키워드 어절이 제목·키워드에 들어간 발행 글 앞 5개(비교용)."""
    toks = {t for t in a["keywords"][0].lower().split() if len(t) >= 2} if a["keywords"] else set()
    rel = [p for p in corpus.arts if p["id"] != a["id"] and p["status"] == "published"
           and any(t in (p["title"] + " " + " ".join(p["keywords"])).lower() for t in toks)]
    return [p["id"] for p in rel[:5]]


